EN_REGIONS = ["en-IN", "en-GB", "en-AU", "en-PH"]  # regional targeting signals: all point at the same standard-English URLs (no separate pages)
def alternates(key):  # [(hreflang, url)] for an English path, or [] if untranslated
    if key not in localized_paths(): return []
    return [("en", canon(key))] + [(h, canon(key)) for h in EN_REGIONS] + [(L.CODE, canon(L.PREFIX+key)) for L in LOCALES] + [("x-default", canon(key))]
def switcher(key, r, cur):
    tr = key in localized_paths() or key == "thanks/index.html"
    links = [("en", "English", r+(key if key != "in/index.html" else "index.html"))] + [(L.CODE, L.NATIVE, r+L.PREFIX+(key if tr else "index.html")) for L in LOCALES]
    curlab = dict((c,lab) for c,lab,_ in links).get(cur, "English") if cur != "india" else "India"
    lis = "".join(f'<li><a href="{h}" hreflang="{c}" lang="{c}"' + (' aria-current="true"' if c == cur else '') + f'>{lab}</a></li>' for c,lab,h in links)
    lis += f'<li class="sep"><a href="{r}in/index.html" lang="en"' + (' aria-current="true"' if cur == "india" else '') + '>India · Indian languages</a></li>'
    return f'<details class="lang"><summary aria-label="Language / भाषा">🌐 {curlab} ▾</summary><ul>{lis}</ul></details>'
