loc_urls = []
for L in LOCALES: loc_urls += build_locale(L)
# English India hub: standard English (same voice as the main site), links to every Indian-language edition; no translated duplicate of English
INDIAN = [L for L in LOCALES if getattr(L, "INDIA", False)]
langcards = "".join(f'<li><a href="@R/{L.PREFIX}index.html" hreflang="{L.CODE}"><span lang="{L.CODE}">{e(L.NATIVE)}</span><small>{e(L.ENGLISH_NAME)} · /{L.PREFIX}</small></a></li>' for L in INDIAN)
names_en = [L.ENGLISH_NAME for L in INDIAN]
names_txt = (", ".join(names_en[:-1]) + " and " + names_en[-1]) if len(names_en) > 1 else "".join(names_en)
NUMW = {1:"one",2:"two",3:"three",4:"four",5:"five",6:"six",7:"seven",8:"eight",9:"nine"}
ucl = "".join(f'<li><a href="@R/use-cases/{u[0]}/index.html">{e(u[1])}</a> — {e(u[2])}</li>' for u in UC)
page("in/index.html", "Best AI tools for Indian builders, by use case", fit(f"Tool Use Cases in {names_txt}, plus English: a free directory of AI tools for vibe coders and builders, ranked by use case."), f"""
<h1>Best AI tools for Indian builders, by use case</h1><p class="lede">Tool Use Cases is a free, editorial directory of AI tools organized by the job you're trying to do — for vibe coders, builders, and anyone shipping with AI. The full site is available in English and {('in ' + names_txt) if len(INDIAN) == 1 else f'in {NUMW.get(len(INDIAN), len(INDIAN))} Indian languages'}.</p>
<h2>Read it in your language</h2><ul class="langs">{langcards}</ul>
<p>Every edition has the same {len(UC)} use cases, the same picks and the same rankings. Only the language changes. Tool names and links stay in English.</p>
<h2>All {len(UC)} use cases (English)</h2><ul>{ucl}</ul>
<p class="muted"><small>Picks are editorial and not paid. Pricing and features change often — check each official site.</small></p>
<p><a href="@R/use-cases/index.html">Browse all use cases →</a></p>""", sw_cur="india", ld=[crumbs(("India","in/")), {"@context":"https://schema.org","@type":"CollectionPage","name":"Best AI tools for Indian builders, by use case","url":BASE+"in/","inLanguage":"en","isPartOf":{"@type":"WebSite","name":"Tool Use Cases","url":BASE},
  "hasPart":[{"@type":"WebSite","name":f"Tool Use Cases ({L.ENGLISH_NAME})","url":BASE+L.PREFIX,"inLanguage":L.CODE} for L in INDIAN]}])
urls.append("in/index.html"); full.append(canon("in/index.html"))
full_loc = [canon(u) for u in loc_urls]
open(f"{OUT}/sitemap.txt","w").write("\n".join(full+full_loc)+"\n")
def sm_entry(u):  # u: site path; alternates for localized pages (Google's xhtml:link sitemap format)
    key = u
    for L in LOCALES:
        if u.startswith(L.PREFIX): key = u[len(L.PREFIX):]
    alts = alternates(key)
    return f"  <url><loc>{canon(u)}</loc>" + "".join(f'<xhtml:link rel="alternate" hreflang="{h}" href="{a}"/>' for h,a in alts) + "</url>\n"
open(f"{OUT}/sitemap.xml","w").write('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xhtml="http://www.w3.org/1999/xhtml">\n'+"".join(sm_entry(u) for u in urls+loc_urls)+"</urlset>\n")
for L in LOCALES:
    U = L.UI
    llms += [f"## {U['llms_h2']}", "", U["llms_intro"], ""]
    llms += [f"- [{n}]({BASE}{L.PREFIX}{p})" for n,p in U["llms_other"]] + [f"- [RSS]({BASE}{L.PREFIX}feed.xml)"]
    llms += [f"- [{L.UC[s][0]}]({BASE}{L.PREFIX}use-cases/{s}/): {L.UC[s][1]}" for s,_,_,_ in UC]
llms += ["## India", "", f"- [Best AI tools for Indian builders, by use case]({BASE}in/): English hub linking to every Indian-language edition ({names_txt}).", ""]
open(f"{OUT}/llms.txt","w").write("\n".join(llms)+"\n")
print("built", len(urls), "English pages +", len(loc_urls), "localized pages (+ thanks) ->", OUT)
